/**
 * pills.tsx
 * General-purpose pill-shaped label components for tags, badges, and status indicators.
 */
import { splitProps, type Component, type JSX, type ParentComponent } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";

import { AdvisorRecommendationItem, type AdvisorRecommendationItemProps } from "./advisor-recommendation.jsx";

// #region Base Pill Components

export interface PillProps extends JSX.HTMLAttributes<HTMLDivElement> {
	/** Additional CSS classes to apply to the container. */
	class?: string;
	/** Inline style for custom backgrounds (e.g., gradients). */
	backgroundStyle?: JSX.CSSProperties;
	/** Reduces overall pill size for denser layouts. */
	small?: boolean;
}

/**
 * A base pill-shaped label component that can be customized with different backgrounds.
 * Used as a foundation for specific pill variants.
 */
export const Pill: ParentComponent<PillProps> = (props) => {
	const [local, other] = splitProps(props, ["class", "backgroundStyle", "children", "small"]);
	const backgroundStyle = () => local.backgroundStyle ?? { "background-color": "#23252b" };
	return (
		<div
			class={`${local.small ? "min-h-6 px-1\\.5" : "min-h-9 px-2"} flex items-center rounded-full leading-normal ${local.class ?? ""}`}
			style={{ border: "1px solid #53565D", ...backgroundStyle() }}
			{...other}
		>
			{local.children}
		</div>
	);
};

export interface PillTextProps extends PillProps {
	/** Localization key for the pill text. */
	text: string;
	/** Optional arguments for the localization string. */
	args?: LocalizedTextArgument[];
}

/**
 * A base pill that displays localized and stylized text.
 */
export const PillText: ParentComponent<PillTextProps> = (props) => {
	const [local, other] = splitProps(props, ["text", "args", "class", "small"]);
	return (
		<Pill
			class={`text-sm ${local.class ?? ""}`}
			small={local.small}
			{...other}
		>
			<L10n.Stylize
				text={local.text}
				args={local.args}
			/>
		</Pill>
	);
};

// #endregion

// #region Advisor Recommendation Pill Components

export interface AdvisorRecommendationPillProps extends AdvisorRecommendationItemProps {
	/** Additional CSS classes to apply to the container. */
	class?: string;
}

/** Gradient background styles for each advisor type. */
const advisorPillGradients: Record<string, JSX.CSSProperties> = {
	"recommendation-cultural": {
		background: "linear-gradient(90deg, #2D1A48 0%, #16101E 100%)",
	},
	"recommendation-economic": {
		background: "linear-gradient(90deg, #453402 0%, #2A2105 100%)",
	},
	"recommendation-military": {
		background: "linear-gradient(90deg, #461314 0%, #2C0A0B 100%)",
	},
	"recommendation-scientific": {
		background: "linear-gradient(90deg, #0E305C 0%, #0A1B30 100%)",
	},
};

/**
 * A pill component that displays an advisor recommendation with an icon and label.
 * Features a gradient background styled according to the advisor type.
 */
export const AdvisorRecommendationPill: Component<AdvisorRecommendationPillProps> = (props) => {
	const [local, other] = splitProps(props, ["class", "recommendation"]);
	const gradientStyle = () => advisorPillGradients[local.recommendation] ?? {};

	return (
		<Pill
			class={`py-1 text-sm ${local.class ?? ""}`}
			backgroundStyle={gradientStyle()}
		>
			<AdvisorRecommendationItem
				recommendation={local.recommendation}
				{...other}
			/>
		</Pill>
	);
};

// #endregion
